import Model from 'flarum/common/Model';
export default class ThreadmarkType extends Model {
  key = (() => Model.attribute('key'))();
  name = (() => Model.attribute('name'))();
  color = (() => Model.attribute('color'))();
  icon = (() => Model.attribute('icon'))();
  position = (() => Model.attribute('position'))();
  isBuiltin = (() => Model.attribute('isBuiltin'))();
  isEnabled = (() => Model.attribute('isEnabled'))();
  canDelete = (() => Model.attribute('canDelete'))();
  createdAt = (() => Model.attribute('createdAt', Model.transformDate))();
  updatedAt = (() => Model.attribute('updatedAt', Model.transformDate))();
}
flarum.reg.add('ffans-threadmarks', 'common/models/ThreadmarkType', ThreadmarkType);